# nginx as a layer 7 load balancer in front of three app servers
upstream app {
    least_conn;                    # pick the server with the fewest active requests
    server 10.0.0.11:8080 max_fails=3 fail_timeout=10s;
    server 10.0.0.12:8080 max_fails=3 fail_timeout=10s;
    server 10.0.0.13:8080 max_fails=3 fail_timeout=10s;
    # max_fails / fail_timeout: stop using a server that keeps failing
}

server {
    listen 80;
    location / {
        proxy_pass http://app;     # forward each request to the pool
    }
}

